package dev.jasper.app.platform;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.SortedSet;
import java.util.TreeSet;
import org.junit.jupiter.api.Test;

class LinuxMimeTest {
    private static final String JASPER = "jasper-workstation-Jasper.desktop";

    @Test void theHighestWeightWinsWhateverItsPlace() {
        String globs2 = """
                # This file was automatically generated by the update-mime-database command. DO NOT EDIT!
                50:text/x-java:*.java
                80:text/x-java-source:*.JAVA
                10:text/plain:*.txt
                """;
        assertThat(LinuxMime.globType(List.of(globs2), "java")).contains("text/x-java-source");
        assertThat(LinuxMime.globType(List.of(globs2), "JAVA")).as("ignoring case").contains("text/x-java-source");
        assertThat(LinuxMime.globType(List.of(globs2), "proto")).isEmpty();
        assertThat(LinuxMime.globType(List.of(), "java")).isEmpty();
    }

    @Test void aCaseSensitivePatternMatchesOnlyItsOwnCase() {
        String globs2 = "50:text/x-c++src:*.C:cs\n50:text/x-csrc:*.c\n";
        assertThat(LinuxMime.globType(List.of(globs2), "c")).contains("text/x-csrc");
        assertThat(LinuxMime.globType(List.of("50:text/x-c++src:*.C:cs\n"), "c")).isEmpty();
        assertThat(LinuxMime.globType(List.of("60:text/x-c++src:*.cc:other-flag\n"), "cc")).as("other flags ignore case")
                .contains("text/x-c++src");
    }

    @Test void aTieGoesToTheEarlierFileAndLine() {
        String user = "50:text/x-jasper-ts:*.ts\n";
        String system = "50:video/mp2t:*.ts\n50:text/vnd.trolltech.linguist:*.ts\n";
        assertThat(LinuxMime.globType(List.of(user, system), "ts")).contains("text/x-jasper-ts");
        assertThat(LinuxMime.globType(List.of(system, user), "ts")).contains("video/mp2t");
        assertThat(LinuxMime.globType(List.of("40:text/x-a:*.ts\n", "60:text/x-b:*.ts\n"), "ts")).contains("text/x-b");
    }

    @Test void malformedLinesAndOtherPatternsAreSkipped() {
        String globs2 = "\nweight:text/x-bad:*.x\n50:text/x-short\n50::*.x\n50:text/x-literal:x\n50:text/x-double:*.tar.x\n"
                + "30:text/x-good:*.x\n";
        assertThat(LinuxMime.globType(List.of(globs2), "x")).contains("text/x-good");
    }

    @Test void removingADefaultKeepsEveryOtherLine() {
        String before = "# mine\r\n[Added Associations]\r\ntext/x-java=vim.desktop;\r\n\r\n[Default Applications]\r\n"
                + "text/x-java=jasper-workstation-Jasper.desktop;code.desktop;\r\ntext/plain=gedit.desktop;\r\n";
        assertThat(LinuxMime.withoutDefault(before, "text/x-java", "jasper-workstation-Jasper.desktop"))
                .isEqualTo(before.replace("text/x-java=jasper-workstation-Jasper.desktop;code.desktop;", "text/x-java=code.desktop;"));
        assertThat(LinuxMime.withoutDefault("[Default Applications]\ntext/x-java=jasper-workstation-Jasper.desktop;\nx=y;\n",
                "text/x-java", "jasper-workstation-Jasper.desktop")).isEqualTo("[Default Applications]\nx=y;\n");
        assertThat(LinuxMime.withoutDefault("[Added Associations]\na=b;\n", "text/x-java", "jasper-workstation-Jasper.desktop"))
                .as("no group: unchanged").isEqualTo("[Added Associations]\na=b;\n");
    }

    @Test void removingADefaultTouchesOnlyThatGroupAndType() {
        String text = "[Added Associations]\ntext/x-java=" + JASPER + ";\n[Default Applications]\ntext/x-javascript=" + JASPER
                + ";\ntext/x-java = a.desktop;" + JASPER + "\n";
        assertThat(LinuxMime.withoutDefault(text, "text/x-java", JASPER)).isEqualTo("[Added Associations]\ntext/x-java=" + JASPER
                + ";\n[Default Applications]\ntext/x-javascript=" + JASPER + ";\ntext/x-java = a.desktop\n");
        assertThat(LinuxMime.withoutDefault("[Default Applications]\ntext/x-java=" + JASPER, "text/x-java", JASPER))
                .as("a last line without a line end").isEqualTo("[Default Applications]\n");
        assertThat(LinuxMime.withoutDefault("", "text/x-java", JASPER)).isEmpty();
    }

    @Test void anAddedAssociationGoesFirstOnce() {
        assertThat(LinuxMime.withAddedAssociation("[Added Associations]\r\ntext/x-proto=vim.desktop;" + JASPER + ";\r\n",
                "text/x-proto", JASPER)).isEqualTo("[Added Associations]\r\ntext/x-proto=" + JASPER + ";vim.desktop;\r\n");
        String first = "[Added Associations]\ntext/x-proto=" + JASPER + ";vim.desktop;\n";
        assertThat(LinuxMime.withAddedAssociation(first, "text/x-proto", JASPER)).as("already first").isEqualTo(first);
        assertThat(LinuxMime.withAddedAssociation("# c\n[Added Associations]\na=b;\n[Default Applications]\nc=d;\n",
                "text/x-proto", JASPER)).isEqualTo("# c\n[Added Associations]\ntext/x-proto=" + JASPER
                + ";\na=b;\n[Default Applications]\nc=d;\n");
    }

    @Test void aMissingGroupIsAddedAtTheEnd() {
        assertThat(LinuxMime.withAddedAssociation("", "text/x-proto", JASPER))
                .isEqualTo("[Added Associations]\ntext/x-proto=" + JASPER + ";\n");
        assertThat(LinuxMime.withAddedAssociation("[Default Applications]\r\nc=d;", "text/x-proto", JASPER))
                .isEqualTo("[Default Applications]\r\nc=d;\r\n\r\n[Added Associations]\r\ntext/x-proto=" + JASPER + ";\r\n");
    }

    @Test void thePackageRoundTrips() {
        SortedSet<String> extensions = new TreeSet<>(List.of("proto", "c++-x", "a_b"));
        String xml = LinuxMime.packageXml(extensions);
        assertThat(xml).startsWith("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<mime-info xmlns=\"http://www.freedesktop.org/standards/shared-mime-info\">\n");
        assertThat(xml).contains("<mime-type type=\"text/x-jasper-proto\"><sub-class-of type=\"text/plain\"/>"
                + "<comment>.proto file</comment><glob pattern=\"*.proto\"/></mime-type>");
        assertThat(xml).contains("<mime-type type=\"text/x-jasper-c++-x\"><sub-class-of type=\"text/plain\"/>"
                + "<comment>.c++-x file</comment><glob pattern=\"*.c++-x\"/></mime-type>");
        assertThat(xml).doesNotContain("&");
        assertThat(LinuxMime.declaredExtensions(xml)).containsExactly("a_b", "c++-x", "proto");
        assertThat(LinuxMime.declaredExtensions(LinuxMime.packageXml(new TreeSet<>()))).isEmpty();
        assertThat(LinuxMime.declaredExtensions("not xml")).isEmpty();
        assertThat(LinuxMime.declaredExtensions("<mime-type type=\"text/x-other\"><glob pattern=\"*.x\"/></mime-type>"))
                .as("only Jasper's own types").isEmpty();
    }

    @Test void theDesktopNameIsTheUnlocalisedNameOfTheMainGroup() {
        assertThat(LinuxMime.desktopName("[Desktop Entry]\nName[de]=Texteditor\nName=Text Editor\nExec=gedit %U\n"))
                .contains("Text Editor");
        assertThat(LinuxMime.desktopName("[Desktop Action new]\nName=New Window\n[Desktop Entry]\nType=Application\n"))
                .as("a Name outside [Desktop Entry]").isEmpty();
        assertThat(LinuxMime.desktopName("[Desktop Entry]\nName=\n")).isEmpty();
        assertThat(LinuxMime.desktopName("Name=Loose\n")).isEmpty();
        assertThat(LinuxMime.desktopName("# c\r\n[Desktop Entry]\r\nName = Code \r\n")).contains("Code");
    }
}
